def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Locate the three-cell pattern, either horizontal or vertical.
    pattern = None
    for r in range(h):
        for c in range(w):
            if c + 2 < w:
                vals = grid[r][c:c+3]
                if all(v != bg for v in vals):
                    pattern = ("h", r, c, vals[:])
                    break
            if r + 2 < h:
                vals = [grid[r+i][c] for i in range(3)]
                if all(v != bg for v in vals):
                    pattern = ("v", r, c, vals)
                    break
        if pattern:
            break

    out = [row[:] for row in grid]
    if pattern is None:
        return out

    orient, pr, pc, vals = pattern
    source = {(pr, pc+i) for i in range(3)} if orient == "h" else {
        (pr+i, pc) for i in range(3)
    }
    marker = next((v for v in counts if v != bg and v not in vals), None)

    if marker is None:
        return out

    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker or (r, c) in source:
                continue
            for i, value in enumerate(vals):
                rr, cc = (r, c+i-1) if orient == "h" else (r+i-1, c)
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    return out
